 public static void Run(){const string ev="Evidence/Target49Niche";Directory.CreateDirectory(ev);try{
 EditorSceneManager.OpenScene("Assets/RuinsTarget49Output/Room.unity");var root=GameObject.Find("ruins_1").transform.parent.gameObject;var c=UnityEngine.Object.FindAnyObjectByType<Camera>();var sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).Single(x=>x.type==LightType.Directional);sun.transform.rotation=Quaternion.Euler(38,-28,0);RenderSettings.ambientLight=Color.gray*.65f;c.orthographic=false;c.backgroundColor=new Color(.075f,.085f,.1f);var from=new Vector3(15,20,19);var at=new Vector3(0,3.5f,0);
