 var old=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget46Output/Structures/Ruins.prefab"));int unchanged=0;foreach(Transform t in old.transform){if(!t.name.StartsWith("ruins_"))continue;var a=t.GetComponent<MeshFilter>().sharedMesh;var b=root.transform.Find(t.name).GetComponent<MeshFilter>().sharedMesh;Check(a.vertices.SequenceEqual(b.vertices)&&a.normals.SequenceEqual(b.normals)&&a.uv.SequenceEqual(b.uv)&&a.triangles.SequenceEqual(b.triangles),"Old geometry "+t.name);Check(root.transform.Find(t.name).GetComponent<MeshCollider>().sharedMesh==b,"Old Collider identity");unchanged++;}Check(unchanged==48,"Old fixture count");
 foreach(int id in new[]{49,50,51,52,53})root.transform.Find("ruins_"+id).gameObject.SetActive(false);root.SetActive(false);var before=Shot(c,from,at,null);old.SetActive(false);root.SetActive(true);Check(before.SequenceEqual(Shot(c,from,at,null)),"Existing pixels changed");UnityEngine.Object.DestroyImmediate(old);
 foreach(Transform t in root.transform)t.gameObject.SetActive(new[]{"ruins_49","ruins_50","ruins_51","ruins_52","ruins_53"}.Contains(t.name));c.orthographic=true;var centre=new Vector3(-7.5f,4.1f,5);
 foreach(string view in new[]{"normal","close","opposite","rear"}){sun.transform.rotation=view=="opposite"?Quaternion.Euler(27,130,0):Quaternion.Euler(38,-28,0);c.orthographicSize=view=="normal"?4.7f:2.5f;Shot(c,centre+new Vector3(view=="rear"?-4:3,3.4f,view=="rear"?-7:7),centre,ev+"/niches-"+view+".png");}
 sun.transform.rotation=Quaternion.Euler(38,-28,0);foreach(int id in new[]{49,51,52,53})root.transform.Find("ruins_"+id).gameObject.SetActive(false);var obj=root.transform.Find("ruins_50").gameObject;var mr=obj.GetComponent<MeshRenderer>();var mf=obj.GetComponent<MeshFilter>();var saved=mf.sharedMesh;var mat=mr.sharedMaterial;c.orthographicSize=1.65f;centre=new Vector3(-6,4.1f,5);Shot(c,centre+new Vector3(2.4f,2.4f,5),centre,ev+"/carved.png");mf.sharedMesh=root.transform.Find("ruins_49").GetComponent<MeshFilter>().sharedMesh;mr.sharedMaterial=root.transform.Find("ruins_49").GetComponent<MeshRenderer>().sharedMaterial;Shot(c,centre+new Vector3(2.4f,2.4f,5),centre,ev+"/plain.png");mf.sharedMesh=saved;mr.sharedMaterial=mat;
 foreach(Transform t in root.transform)t.gameObject.SetActive(true);Physics.SyncTransforms();int rays=0;foreach(int id in new[]{49,50}){var col=root.transform.Find("ruins_"+id).GetComponent<MeshCollider>();float x=id==49?-9:-6;Check(col.sharedMesh==col.GetComponent<MeshFilter>().sharedMesh,"Collider identity");Check(col.Raycast(new Ray(new Vector3(x,4.2f,6),Vector3.back),out var back,2),"Back missing");Check(Math.Abs(back.point.z-4.97f)<.04f,"Recess depth");Check(col.Raycast(new Ray(new Vector3(x+.8f,4.2f,6),Vector3.back),out var jamb,2),"Jamb missing");Check(jamb.point.z-back.point.z>.2f,"Not recessed");rays+=2;
 var walker=new GameObject("NicheWalker");var cc=walker.AddComponent<CharacterController>();cc.height=1.6f;cc.center=new Vector3(0,.8f,0);cc.radius=.25f;cc.skinWidth=.015f;cc.stepOffset=.25f;walker.transform.position=new Vector3(x,3.03f,6);Physics.SyncTransforms();for(int k=0;k<40;k++)cc.Move(new Vector3(0,-.025f,-.05f));Check(walker.transform.position.z>5.4f,"Blind wall crossed "+id);UnityEngine.Object.DestroyImmediate(walker);
 foreach(int count in new[]{9,225}){var clones=Enumerable.Range(0,count).Select(k=>{var o=UnityEngine.Object.Instantiate(col.gameObject);o.transform.position=new Vector3(100+k*5,0,100);return o;}).ToArray();Check(clones.Select(o=>o.GetComponent<MeshFilter>().sharedMesh).Distinct().Count()==1&&clones.Select(o=>o.GetComponent<MeshRenderer>().sharedMaterial).Distinct().Count()==1,"Shared references");foreach(var o in clones)UnityEngine.Object.DestroyImmediate(o);}}
 int jointRays=0;foreach(float x in new[]{-10f,-8f,-7f,-5f})foreach(float dx in new[]{-.003f,0,.003f})for(float y=3.1f;y<5.02f;y+=.12f){Check(Physics.Raycast(new Ray(new Vector3(x+dx,y,6),Vector3.back),out var joint,1.3f)&&joint.collider.name.StartsWith("ruins_"),"Wall joint gap");jointRays++;}
 Check(!ShaderUtil.ShaderHasError(mat.shader),"Shader error");File.WriteAllText(ev+"/result.json","{\"pass\":true,\"oldMeshes\":48,\"prefabScenePixelDelta\":0,\"otherPartsPixelDelta\":0,\"capsuleBlocked\":2,\"recessRays\":"+rays+",\"jointRays\":"+jointRays+",\"shared9And225Offscreen\":true,\"GPUmeasured\":false}");EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(ev+"/failure.txt",e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
}
